mkdir -p inspect cmd/inspect-demo && cat > inspect/inspect.go <<'EOF'
// Package inspect deeply pretty-prints arbitrary Go values for debugging.
//
// It wraps github.com/davecgh/go-spew, which walks values via reflection,
// follows pointers, prints unexported fields, and detects cycles.
package inspect

import (
	"io"

	"github.com/davecgh/go-spew/spew"
)

// Config controls the dump output.
var Config = spew.ConfigState{
	Indent:                  "  ",
	SortKeys:                true, // deterministic map output
	DisablePointerAddresses: true, // stable output across runs
	DisableCapacities:       true,
	SpewKeys:                true,
}

// Sdump returns a deep, multi-line representation of the given values.
func Sdump(values ...any) string { return Config.Sdump(values...) }

// Dump writes a deep representation of the given values to stdout.
func Dump(values ...any) { Config.Dump(values...) }

// Fdump writes a deep representation of the given values to w.
func Fdump(w io.Writer, values ...any) { Config.Fdump(w, values...) }
EOF
cat > inspect/inspect_test.go <<'EOF'
package inspect

import (
	"strings"
	"testing"
)

type node struct {
	Name     string
	secret   int
	Children []*node
	Parent   *node
	Meta     map[string]any
}

func TestSdumpNestedAndCyclic(t *testing.T) {
	root := &node{Name: "root", secret: 42, Meta: map[string]any{"b": 2, "a": []int{1}}}
	child := &node{Name: "child", Parent: root}
	root.Children = append(root.Children, child)

	out := Sdump(root)
	for _, want := range []string{`"root"`, `"child"`, "secret: (int) 42", "already shown"} {
		if !strings.Contains(out, want) {
			t.Errorf("output missing %q:\n%s", want, out)
		}
	}
	if strings.Index(out, `"a"`) > strings.Index(out, `"b"`) {
		t.Errorf("map keys not sorted:\n%s", out)
	}
}
EOF
cat > cmd/inspect-demo/main.go <<'EOF'
// Command inspect-demo shows the output of the inspect package.
package main

import "github.com/example/inspect/inspect"

type config struct {
	Name    string
	Ports   []int
	Labels  map[string]string
	Backend *config
	private bool
}

func main() {
	c := &config{
		Name:    "api",
		Ports:   []int{80, 443},
		Labels:  map[string]string{"env": "prod", "app": "web"},
		Backend: &config{Name: "db", Ports: []int{5432}},
		private: true,
	}
	c.Backend.Backend = c // cycle
	inspect.Dump(c)
}
EOF
